import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uniform, uv, vec2, vec3, mix, smoothstep, hash, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DataTexture, RGBAFormat } = ctx.THREE;

  const group = new Group();
  group.name = 'collection-card-2';

  // Spec colors as TSL vec3 constants
  // #0b0b10 surface, #16161d ink, #ff2a38 accent, #e8ecf2 paper
  const SURFACE = vec3(0.043, 0.043, 0.063);
  const INK = vec3(0.086, 0.086, 0.114);
  const ACCENT = vec3(1.0, 0.165, 0.220);
  const PAPER = vec3(0.910, 0.925, 0.949);

  // Card dimensions (512:320 = 1.6:1 aspect)
  const cardW = 3.2;
  const cardH = 2.0;
  const pad = 0.08;

  // Inner group for entrance animation (adapter sets outer position)
  const inner = new Group();
  group.add(inner);

  // ── Backing panel: engineered gradient (surface → ink) ──
  const panelGeo = new PlaneGeometry(cardW + pad * 2, cardH + pad * 2);
  const panelMat = new MeshBasicNodeMaterial({ transparent: true });
  panelMat.colorNode = mix(SURFACE, INK, smoothstep(0.0, 1.0, uv().y));
  panelMat.opacity = 0;
  const panel = new Mesh(panelGeo, panelMat);
  panel.position.z = -0.02;
  inner.add(panel);

  // ── Fallback texture (1×1 dark pixel) ──
  const fallbackData = new Uint8Array([11, 11, 16, 255]);
  const fallbackTex = new DataTexture(fallbackData, 1, 1, RGBAFormat);
  fallbackTex.needsUpdate = true;
  const texUniform = uniform(fallbackTex);

  // ── Main image plane: texture + static grain + vignette ──
  const cardGeo = new PlaneGeometry(cardW, cardH);
  const cardMat = new MeshBasicNodeMaterial({ transparent: true });

  // Subtle static film grain
  const grain = hash(uv().mul(vec2(512.0, 320.0))).sub(0.5).mul(0.022);
  // Radial vignette
  const vDist = uv().sub(vec2(0.5, 0.5)).length();
  const vFactor = float(1.0).sub(smoothstep(0.35, 0.8, vDist).mul(0.35));
  // Composite: texture * vignette + grain
  cardMat.colorNode = texture(texUniform, uv()).mul(vFactor).add(vec3(grain));
  cardMat.opacity = 0;

  const card = new Mesh(cardGeo, cardMat);
  card.position.z = 0.01;
  inner.add(card);

  // ── Accent bar (bottom edge — signal red, <=10% frame) ──
  const accentGeo = new PlaneGeometry(cardW + pad * 2, 0.03);
  const accentMat = new MeshBasicNodeMaterial({ transparent: true });
  accentMat.colorNode = ACCENT;
  accentMat.opacity = 0;
  const accentBar = new Mesh(accentGeo, accentMat);
  accentBar.position.set(0, -(cardH + pad * 2) / 2 + 0.015, 0.02);
  inner.add(accentBar);

  // ── Top hairline (subtle paper-tinted border) ──
  const hairlineGeo = new PlaneGeometry(cardW + pad * 2, 0.008);
  const hairlineMat = new MeshBasicNodeMaterial({ transparent: true });
  hairlineMat.colorNode = mix(INK, PAPER, float(0.12));
  hairlineMat.opacity = 0;
  const hairline = new Mesh(hairlineGeo, hairlineMat);
  hairline.position.set(0, (cardH + pad * 2) / 2 - 0.004, 0.02);
  inner.add(hairline);

  // ── Load texture asynchronously ──
  const imageUrl = config.imageUrl || config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      if (ctx.THREE.SRGBColorSpace) {
        tex.colorSpace = ctx.THREE.SRGBColorSpace;
      }
      texUniform.value = tex;
    });
  }

  // ── Entrance animation (rise-in + weighted-settle) ──
  inner.position.y = 0.35;
  inner.scale.setScalar(0.97);

  const tl = gsap.timeline();
  tl.to(inner.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0)
    .to(inner.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0)
    .to(panelMat, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0)
    .to(cardMat, { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0.1)
    .to(accentMat, { opacity: 0.85, duration: 0.4, ease: 'power2.out' }, 0.3)
    .to(hairlineMat, { opacity: 0.4, duration: 0.4, ease: 'power2.out' }, 0.35);

  // ── Handlers (static node — no interactivity) ──
  group.userData.handlers = {};

  // ── Cleanup ──
  group.userData.cleanup = () => {
    tl.kill();
    panelGeo.dispose();
    cardGeo.dispose();
    accentGeo.dispose();
    hairlineGeo.dispose();
    panelMat.dispose();
    cardMat.dispose();
    accentMat.dispose();
    hairlineMat.dispose();
    fallbackTex.dispose();
  };

  return group;
}
